//! 🧭️ Foreign IO phases never create or observe an inactive native ledger.
#[test]
fn original_snapshot_body_wallet_preserves_exact_authored_span_currencies(){
 use semio_framework_value::{RetainedCloneGrant,retained_clone::RetainedCloneProgress};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let policy=&neutral["producer"];let grant:RetainedCloneGrant=serde_json::from_value(policy["walletGrant"].clone()).unwrap();let mut wallet=super::NativeSnapshotBodyWallet::new(grant);
 for row in policy["receipts"].as_array().unwrap(){let progress:RetainedCloneProgress=serde_json::from_value(row.clone()).unwrap();let demand=RetainedCloneGrant{maximum_items:progress.copied_items,maximum_copy_bytes:progress.copied_bytes,maximum_capacity_bytes:progress.retained_capacity_bytes,maximum_release_bytes:progress.released_bytes,maximum_depth:grant.maximum_depth};wallet.admit_frontier(demand).unwrap();wallet.record_progress(progress).unwrap();}
 assert_eq!(serde_json::to_value(wallet.remaining_grant()).unwrap(),policy["remainingGrant"]);let original=wallet.progress();
 for axis in 0..5{let mut denied=wallet.remaining_grant();match axis{0=>denied.maximum_items+=1,1=>denied.maximum_copy_bytes+=1,2=>denied.maximum_capacity_bytes+=1,3=>denied.maximum_release_bytes+=1,4=>denied.maximum_depth+=1,_=>unreachable!()}assert!(wallet.admit_frontier(denied).is_err());assert_eq!(wallet.progress(),original);}
 assert!(wallet.record_progress(RetainedCloneProgress{copied_bytes:1,..Default::default()}).is_err());assert_eq!(wallet.progress(),original);println!("[DEBUG] Original producer wallet exactAuthoredSpans=true fivePrebirthDenials=true refusalUnchanged=true independentSerde=true");
}
#[test]
fn original_snapshot_decoder_body_receipt_is_debited_before_cleanup_and_preserved_on_refusal(){
 use semio_framework_value::{native_decoding::NativeDecodeRetirementRecipient,retained_clone::RetainedCloneProgress,RetainedCloneGrant};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let text=fixture["copy"].as_str().unwrap();let policy=&fixture["producer"];
 let demand=RetainedCloneGrant{maximum_items:policy["items"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:policy["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:policy["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:policy["depth"].as_u64().unwrap()as usize};
 for cancelled in [false,true]{
  let live=Cell::new(true);let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|{if cancelled&&event.total==text.len()&&event.completed==text.len(){live.set(false)}live.get()};let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(fixture["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let grant=fixture_grant();let pointer=Cell::new(std::ptr::null::<u8>());let measured=Cell::new(RetainedCloneProgress::default());let mut owner=super::NativeSnapshotDecodeOwner::new(&mut native,grant);
  let result=owner.receive::<String,String>(|destination,native,body|{
   let remaining=body.remaining_grant();assert_eq!(remaining.maximum_items,grant.maximum_items-1);assert!(remaining.maximum_capacity_bytes<grant.maximum_capacity_bytes);assert_eq!(remaining.maximum_depth,grant.maximum_depth-1);body.admit_frontier(demand)?;*destination=Some(String::new());
   let copied=body.copy_text_into(native,text,destination.as_mut().unwrap(),demand.maximum_depth);let original=destination.as_ref().unwrap();measured.set(body.progress());copied?;pointer.set(original.as_ptr());Ok(destination.take().unwrap())
  });
  let progress=owner.progress();assert_eq!(owner.grant(),grant);let copied=&policy["retirementCopy"];let header=copied["headers"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();assert_eq!(std::mem::size_of::<Option<String>>(),header["headerBytes"].as_u64().unwrap()as usize);assert_eq!(copied["payloadBytes"].as_u64().unwrap()+(copied["intermediateHeaderCount"].as_u64().unwrap()+copied["publicationHeaderCount"].as_u64().unwrap())*header["headerBytes"].as_u64().unwrap(),header["aggregateBytes"].as_u64().unwrap());assert_eq!(measured.get().copied_bytes,copied["payloadBytes"].as_u64().unwrap()as usize);println!("[DEBUG] Original decoded receipt cancelled={cancelled} payload={} structuralHeader={} aggregate={}",measured.get().copied_bytes,if cancelled{0}else{header["headerBytes"].as_u64().unwrap()},progress.copied_bytes);assert_eq!(progress.copied_bytes,if cancelled{copied["cancelledBytes"].as_u64().unwrap()}else{header["aggregateBytes"].as_u64().unwrap()}as usize);assert!(progress.retained_capacity_bytes>=measured.get().retained_capacity_bytes);assert!(progress.fits(grant));drop(owner);
  if cancelled{let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),progress);assert!(native.has_retirement_owner());live.set(true);while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();}}
  else{let output=result.unwrap();assert_eq!(output.as_ptr(),pointer.get());assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(text).unwrap());assert!(!native.has_retirement_owner());let mut retirement=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).unwrap_or_else(|_|unreachable!());while !retirement.terminal_is_empty(){retirement.step(grant).unwrap();}}
  drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original snapshot producer cancelled={} actualDestinationReceipt=true originalWalletDebited=true refusalReceiptPreserved=true movedOutput=true independentSerde=true",cancelled);
 }
}
use super::{IoRunControl,IoNativeDirection};
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,ValueRefusalKind};
use std::cell::Cell;
fn fixture_grant()->semio_framework_value::RetainedCloneGrant{let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();serde_json::from_value(neutral["cases"][0]["grant"].clone()).unwrap()}
#[test]
fn foreign_io_direction_observes_one_original_phase_and_refuses_the_opposite(){
 let decode_calls=Cell::new(0);let mut progress=|_|{decode_calls.set(decode_calls.get()+1);true};let mut original=NativeDecodeControl::new(3,&mut progress);let mut io=IoRunControl::decoding(&mut original,fixture_grant());io.checkpoint().unwrap();io.decode().unwrap().copy_text("雪").unwrap();assert_eq!(io.encode().err().unwrap().kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(io.direction(),IoNativeDirection::Decode);io.checkpoint().unwrap();drop(io);assert_eq!(original.owned_bytes(),3);assert_eq!(decode_calls.get(),4);
 let calls=Cell::new(0);let mut progress=|_|{calls.set(calls.get()+1);true};let mut original=NativeEncodeControl::new(3,&mut progress);let mut io=IoRunControl::encoding(&mut original,fixture_grant());io.checkpoint().unwrap();io.encode().unwrap().copy_text("雪").unwrap();assert_eq!(io.decode().err().unwrap().kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(io.direction(),IoNativeDirection::Encode);drop(io);assert_eq!(original.owned_bytes(),3);assert!(calls.get()>0);
 println!("[DEBUG] IO foreign receiving direction: originalDecodeOnly=true originalEncodeOnly=true noInactiveControl=true oppositeDirectionTypedRefusal=true originalOwnershipRetained=true");
}
#[test]
fn original_native_io_phase_transition_finishes_previous_lifetime_before_observing_next(){
 let decode_allowed=Cell::new(true);let encode_calls=Cell::new(0);let mut decode_progress=|_|decode_allowed.get();let mut encode_progress=|_|{encode_calls.set(encode_calls.get()+1);true};let mut decode=NativeDecodeControl::new(3,&mut decode_progress);let mut encode=NativeEncodeControl::new(3,&mut encode_progress);let mut io=IoRunControl::new(&mut decode,&mut encode,fixture_grant());io.decode().unwrap().copy_text("雪").unwrap();decode_allowed.set(false);assert_eq!(io.encode().err().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!(io.direction(),IoNativeDirection::Decode);assert_eq!(encode_calls.get(),0);decode_allowed.set(true);io.encode().unwrap().copy_text("雪").unwrap();assert_eq!(io.direction(),IoNativeDirection::Encode);drop(io);assert_eq!(decode.owned_bytes(),3);assert_eq!(encode.owned_bytes(),3);
 println!("[DEBUG] IO original phase transition: previousOriginalCancelPrecedesNextObserver=true exactCumulativeNativeLedgers=true");
}

