#[test]
fn original_snapshot_encoder_returns_refused_retirement_and_commits_only_after_terminal_drain(){
 use semio_framework_value::native_encoding::NativeEncodeRetirementRecipient;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let text=fixture["copy"].as_str().unwrap();
 for refused in [false,true]{let mut recipient=NativeEncodeRetirementRecipient::new();let mut progress=|_|true;let mut native=NativeEncodeControl::new(fixture["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let mut grant=fixture_grant();if refused{grant.maximum_release_bytes=0;}let mut owner=super::NativeSnapshotEncodeOwner::new(&mut native,grant);let result=owner.receive::<Vec<String>,String>(|intermediate,native,_body|{*intermediate=Some(native.allocate_vec(1)?);intermediate.as_mut().unwrap().push(native.copy_text(text)?);native.copy_text(text)});drop(owner);if refused{assert!(result.is_err());assert!(native.has_retirement_owner());assert!(native.close_retirement_recipient(grant).is_err()||native.has_retirement_owner());assert!(native.has_retirement_owner());while native.has_retirement_owner(){native.close_retirement_recipient(fixture_grant()).unwrap();}}else{assert_eq!(serde_json::to_value(result.unwrap()).unwrap(),serde_json::to_value(text).unwrap());assert!(!native.has_retirement_owner());}drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original snapshot intermediate retirement refused={} exactIndependentGrant=true originalRecipient=true independentSerde=true",refused);}
}

#[test]
fn returned_snapshot_retirement_keeps_original_allocation_port_during_physical_drain(){
 use semio_framework_value::native_encoding::{NativeEncodeRetirementRecipient,NativeEncodeAllocation};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let text=neutral["copy"].as_str().unwrap();let mut recipient=NativeEncodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let allocations=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:NativeEncodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);allocations.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut native=NativeEncodeControl::new_forwarded(neutral["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut progress,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut grant=fixture_grant();grant.maximum_release_bytes=0;let mut owner=super::NativeSnapshotEncodeOwner::new(&mut native,grant);assert!(owner.receive::<Vec<String>,String>(|intermediate,native,_body|{*intermediate=Some(native.allocate_vec(1)?);intermediate.as_mut().unwrap().push(native.copy_text(text)?);native.copy_text(text)}).is_err());drop(owner);assert!(native.has_retirement_owner());let before=native.owned_bytes();let calls=allocations.load(std::sync::atomic::Ordering::Relaxed);while native.has_retirement_owner(){native.close_retirement_recipient(fixture_grant()).unwrap();assert_eq!(native.owned_bytes(),ledger.load(std::sync::atomic::Ordering::Relaxed));}assert!(native.owned_bytes()>before);assert!(allocations.load(std::sync::atomic::Ordering::Relaxed)>calls);drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original returned snapshot drain samePort=true cumulativeOwned=true physicalCursorReservationsForwarded=true terminalRelease=true");
}

