#[test]
fn native_snapshot_paid_wallet_preserves_all_axes_and_refused_receipt(){
 use semio_framework_value::{RetainedCloneGrant,retained_clone::RetainedCloneProgress};
 let grant=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:8,maximum_capacity_bytes:64,maximum_release_bytes:64,maximum_depth:4};
 let mut callback=|_|true;let mut native=NativeEncodeControl::new(1024,&mut callback);let mut owner=super::NativeSnapshotEncodeOwner::new(&mut native,grant);
 let first=RetainedCloneProgress{copied_items:1,copied_bytes:8,retained_capacity_bytes:64,released_bytes:0};
 owner.record_progress(first).unwrap();assert_eq!(owner.progress(),first);
 let remaining=owner.remaining_grant();assert_eq!(remaining,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:64,maximum_depth:4});
 for denied in [RetainedCloneProgress{copied_items:2,..Default::default()},RetainedCloneProgress{copied_bytes:1,..Default::default()},RetainedCloneProgress{retained_capacity_bytes:1,..Default::default()},RetainedCloneProgress{released_bytes:65,..Default::default()}]{assert!(owner.record_progress(denied).is_err());assert_eq!(owner.progress(),first);assert_eq!(owner.remaining_grant(),remaining);}
 let second=RetainedCloneProgress{copied_items:1,copied_bytes:0,retained_capacity_bytes:0,released_bytes:64};owner.record_progress(second).unwrap();
 let expected:RetainedCloneProgress=serde_json::from_str(r#"{"copiedItems":2,"copiedBytes":8,"retainedCapacityBytes":64,"releasedBytes":64}"#).unwrap();
 assert_eq!(owner.progress(),expected);assert_eq!(owner.remaining_grant(),RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:4});assert_eq!(owner.grant(),grant);assert_eq!(owner.native().owned_bytes(),0);
 println!("[DEBUG] Native encode receipt wallet independentPolicy=true originalGrant=true refusalUnchanged=true nativeAllocationNotGuessed=true");
}

#[test]
fn native_snapshot_cursor_retains_paid_original_on_cancellation_and_commits_same_output(){
 use semio_framework_value::{native_encoding::NativeEncodeRetirementRecipient,retained_clone::RetainedCloneProgress};
 for cancelled in [false,true]{
  let live=Cell::new(true);let mut callback=|_|live.get();let mut recipient=NativeEncodeRetirementRecipient::new();let mut native=NativeEncodeControl::new(1<<30,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();
  let mut cursor=Some(Vec::<u8>::new());let grant=fixture_grant();let mut phase=false;let mut pointer=std::ptr::null();let mut owner=super::NativeSnapshotEncodeOwner::new(&mut native,grant);
  let result=owner.drive_cursor(&mut cursor,|cursor,native,remaining|{
   if !phase{
    if remaining.maximum_copy_bytes<3||remaining.maximum_capacity_bytes<3{return(Err(semio_framework_value::ValueError::literal(ValueRefusalKind::OwnershipLimit,"test cursor physical frontier denied")),Default::default())}
    match native.allocate_vec::<u8>(3){Ok(bytes)=>{*cursor=bytes;cursor.extend_from_slice("雪".as_bytes());pointer=cursor.as_ptr();phase=true;live.set(!cancelled);(Ok(None),RetainedCloneProgress{copied_items:1,copied_bytes:3,retained_capacity_bytes:cursor.capacity(),released_bytes:0})},Err(error)=>(Err(error),Default::default())}
   }else{(Ok(Some(std::mem::take(cursor))),RetainedCloneProgress{copied_items:1,..Default::default()})}
  });
  let progress=owner.progress();assert_eq!(owner.grant(),grant);assert!(progress.fits(grant));assert!(progress.retained_capacity_bytes>=3);let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let copied=&neutral["producer"]["cursorRetirementCopy"];let header=copied["headers"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();assert_eq!(std::mem::size_of::<Option<Vec<u8>>>(),header["headerBytes"].as_u64().unwrap()as usize);assert_eq!(copied["payloadBytes"].as_u64().unwrap()+(copied["intermediateHeaderCount"].as_u64().unwrap()+copied["publicationHeaderCount"].as_u64().unwrap())*header["headerBytes"].as_u64().unwrap(),header["aggregateBytes"].as_u64().unwrap());println!("[DEBUG] Original cursor receipt cancelled={cancelled} payload={} structuralHeader={} aggregate={}",copied["payloadBytes"],if cancelled{0}else{header["headerBytes"].as_u64().unwrap()},progress.copied_bytes);assert_eq!(progress.copied_bytes,if cancelled{copied["cancelledBytes"].as_u64().unwrap()}else{header["aggregateBytes"].as_u64().unwrap()}as usize);drop(owner);assert!(cursor.is_none());
  if cancelled{let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),progress);assert!(native.has_retirement_owner());live.set(true);while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();}}
  else{let output=result.unwrap();assert_eq!(output.as_ptr(),pointer);assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value("雪".as_bytes()).unwrap());assert!(!native.has_retirement_owner());let mut retirement=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).unwrap_or_else(|_|unreachable!());while !retirement.terminal_is_empty(){retirement.step(grant).unwrap();}}
  drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original native cursor cancelled={} sameOutputPointerOnSuccess=true independentSerde=true paidFrameAndFrontier=true originalReturnSlotOnCancel=true",cancelled);
 }
}

