#[test]
fn original_nested_receiving_preserves_actual_child_in_one_original_recipient(){
 use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,ValueError};
 use std::sync::atomic::{AtomicUsize,Ordering};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🪆️receiving/🔣️.json")).unwrap();let text=neutral["text"].as_str().unwrap();let grant:RetainedCloneGrant=serde_json::from_value(neutral["grant"].clone()).unwrap();let maximum=neutral["nativeMaximumBytes"].as_u64().unwrap()as usize;
 macro_rules! receiving{($control:path,$recipient:path,$request:path,$owner:path,$copy:expr)=>{{for case in neutral["cases"].as_array().unwrap(){
  let live=Cell::new(true);let ledger=AtomicUsize::new(0);let events=AtomicUsize::new(0);let mut allocation=|request:$request|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));ledger.store(request.next_owned_bytes,Ordering::Relaxed);events.fetch_add(1,Ordering::Relaxed);Ok(())};let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|{if case["cancelChild"].as_bool().unwrap()&&event.total==text.len()&&event.completed==text.len(){live.set(false)}live.get()};
  let mut recipient=<$recipient>::new();let mut native=<$control>::new_forwarded(maximum,&mut callback,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=<$owner>::new(&mut native,grant);let pointer=Cell::new(std::ptr::null::<u8>());
  let(result,born,released)=crate::test_allocation::observe_backing(||owner.receive_nested::<String,String>(|parent,original|{
   let scoped_events=Cell::new(0usize);let mut scoped=|event:semio_framework_value::native_decoding::NativeDecodeProgress|{assert_eq!(event.owned_bytes,ledger.load(Ordering::Relaxed));scoped_events.set(scoped_events.get()+1);live.get()};let child=original.scoped_native(maximum,&mut scoped,|original|original.receive::<String,String>(|slot,native,body|{body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:text.len(),maximum_capacity_bytes:text.len(),maximum_release_bytes:0,maximum_depth:1})?;*slot=Some(String::new());let copied=($copy)(text,slot.as_mut().unwrap(),native);let actual=slot.as_ref().unwrap();body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:actual.len(),retained_capacity_bytes:actual.capacity(),released_bytes:0})?;copied?;pointer.set(actual.as_ptr());Ok(slot.take().unwrap())}))?;assert!(scoped_events.get()>0);
   *parent=Some(child);if case["cancelParent"].as_bool().unwrap(){live.set(false);original.native().checkpoint()?;}Ok(parent.take().unwrap())
  }));let progress=owner.progress();assert!(progress.fits(grant));assert_eq!(owner.grant(),grant);drop(owner);assert!(born>=text.len());assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));
  if case["published"].as_bool().unwrap(){let output=result.unwrap();assert_eq!(output.as_ptr(),pointer.get());assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(text).unwrap());assert!(!native.has_retirement_owner());let mut returned=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).unwrap();while !returned.terminal_is_empty(){let capacity=returned.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();native.checkpoint().unwrap();native.charge(capacity).unwrap();returned.step(grant).unwrap();}}
  else{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(released,progress.released_bytes,"only actual originally funded child publication may release backing before parent refusal");if case["cancelChild"].as_bool().unwrap(){assert_eq!(released,0);}assert!(native.has_retirement_owner());live.set(true);while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));}}
  assert!(events.load(Ordering::Relaxed)>=2);drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original nested receiving {} oneOriginalRecipient=true childTicketRetained=true originalPortEveryReserve=true cumulativeFiveAxisReceipts=true independentSerde=true",case["id"]);
 }}};}
 receiving!(semio_framework_value::NativeDecodeControl,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,semio_framework_value::native_decoding::NativeDecodeAllocation,super::NativeSnapshotDecodeOwner,|text:&str,slot:&mut String,native:&mut semio_framework_value::NativeDecodeControl<'_>|native.copy_text_into(text,slot));
}

