 if result.is_err(){assert_eq!(released,progress.released_bytes);live.set(true);while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));}}
 if case["published"].as_bool().unwrap(){let output=result.unwrap();assert_eq!(output.as_ptr(),pointer.get());assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(text).unwrap());let mut returned=semio_framework_value::retirement::controlled::ControlledRetirement::new(output).unwrap();while !returned.terminal_is_empty(){let capacity=returned.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();native.checkpoint().unwrap();native.charge(capacity).unwrap();returned.step(grant).unwrap();}}else{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(born>=text.len());}
