#[test]
fn native_snapshot_body_octets_keep_actual_cancelled_backing_and_cumulative_authority(){
 use super::NativeSnapshotBodyWallet;
 use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,retirement::controlled::ControlledRetirement};
 let plain:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🪆️receiving/🔣️.json")).unwrap();let row=&plain["bodyCopy"];
 let source=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize).into_bytes();let cancel_at=row["cancelAt"].as_u64().unwrap()as usize;
 let normal:RetainedCloneGrant=serde_json::from_value(row["grant"].clone()).unwrap();let close:RetainedCloneGrant=serde_json::from_value(row["closeGrant"].clone()).unwrap();
 for denied in [RetainedCloneGrant{maximum_items:0,..normal},RetainedCloneGrant{maximum_copy_bytes:source.len()-1,..normal},RetainedCloneGrant{maximum_capacity_bytes:source.len()-1,..normal},RetainedCloneGrant{maximum_depth:0,..normal}]{
  let calls=Cell::new(0usize);let mut callback=|_|{calls.set(calls.get()+1);true};let mut native=NativeDecodeControl::new(row["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);let mut wallet=NativeSnapshotBodyWallet::new(denied);let mut output=Vec::new();
  let(result,born,released)=crate::test_allocation::observe_backing(||wallet.copy_bytes_into(&mut native,&source,&mut output,1));assert!(result.is_err());assert_eq!((born,released),(0,0));assert_eq!((output.len(),output.capacity(),native.owned_bytes(),calls.get()),(0,0,0,0));assert_eq!(wallet.progress(),RetainedCloneProgress::default());assert_eq!(wallet.remaining_grant(),denied);
 }
 for cancelled in [false,true]{
  let reached=Cell::new((0usize,0usize));let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|{if event.total==source.len(){reached.set((reached.get().0+1,event.completed));!cancelled||event.completed<cancel_at}else{true}};
  let mut native=NativeDecodeControl::new(row["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);let mut wallet=NativeSnapshotBodyWallet::new(normal);let mut output=Vec::new();
  let(result,born,released)=crate::test_allocation::observe_backing(||wallet.copy_bytes_into(&mut native,&source,&mut output,1));let performed=wallet.progress();
  assert_eq!((born,released),(output.capacity(),0));assert_eq!(performed,RetainedCloneProgress{copied_items:1,copied_bytes:output.len(),retained_capacity_bytes:output.capacity(),released_bytes:0});assert!(performed.fits(normal));assert_eq!(output,source[..output.len()]);
  if cancelled{let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),performed);assert_eq!(output.len(),cancel_at);assert_eq!(reached.get(),(2,cancel_at));}else{result.unwrap();assert_eq!(output,source);}
  let pointer=output.as_ptr();let remaining=wallet.remaining_grant();assert_eq!(remaining.maximum_release_bytes,normal.maximum_release_bytes);assert_eq!(remaining.maximum_depth,normal.maximum_depth);
  let before=(output.len(),output.capacity(),native.owned_bytes(),reached.get());let(result,new_born,new_released)=crate::test_allocation::observe_backing(||wallet.copy_bytes_into(&mut native,&source,&mut output,1));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvariantViolated);assert_eq!((new_born,new_released),(0,0));assert_eq!((output.as_ptr(),output.len(),output.capacity(),native.owned_bytes(),reached.get()),(pointer,before.0,before.1,before.2,before.3));assert_eq!(wallet.progress(),performed);
  let mut second=Vec::new();let(result,new_born,new_released)=crate::test_allocation::observe_backing(||wallet.copy_bytes_into(&mut native,&source,&mut second,1));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!((new_born,new_released),(0,0));assert_eq!((second.len(),second.capacity()),(0,0));assert_eq!(wallet.remaining_grant(),remaining);assert_eq!(native.owned_bytes(),before.2);
  drop(native);drop(callback);assert_eq!(serde_json::from_str::<Vec<u8>>(&serde_json::to_string(&output).unwrap()).unwrap(),source[..output.len()]);
  let(admitted,extra,freed)=crate::test_allocation::observe_backing(||ControlledRetirement::new(output));assert_eq!(freed,0);let mut owner=admitted.unwrap_or_else(|(error,_)|panic!("{error}"));let(mut allocated,mut retired)=(born+extra,0);
  for _ in 0..row["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let(step,birth,release)=crate::test_allocation::observe_backing(||owner.step(close).unwrap());assert!(step.progress().fits(close));assert_eq!((birth,release),(step.progress().retained_capacity_bytes,step.progress().released_bytes));allocated+=birth;retired+=release;}
  assert!(owner.terminal_is_empty());assert_eq!(retired,allocated);assert_eq!(crate::test_allocation::observe_backing(||drop(owner)),((),0,0));
  println!("[DEBUG] Native octet body cancelled={cancelled} originalPointer=true zeroEffectDenial=true fixedIndependentPolicy=true actualPrefixCapacityReceipt=true cumulativeRefusal=true SystemAllocatedFreed={allocated} independentSerde=true");
 }
}

#[test]
fn original_optional_and_deferred_child_receipts_share_one_existing_frontier(){
 use semio_framework_value::{NativeDecodeControl,RetainedCloneGrant,RetainedCloneProgress,retirement::{RetireOwned,RetirementStep}};
 struct OriginalField{text:String,pointer:usize}
 impl RetireOwned for OriginalField{fn retirement(self)->Box<dyn semio_framework_value::retirement::RetirementCursor>{assert_eq!(self.text.as_ptr()as usize,self.pointer,"original child receives the same payload backing");assert_eq!(self.text,"雪");self.text.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.text.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🛫️snapshot/🧫️fixtures/🔣️.json")).unwrap();let law=&neutral["originalFieldChild"];let caller:RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();let row=law["headers"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();let header=row["headerBytes"].as_u64().unwrap()as usize;assert_eq!(std::mem::size_of::<OriginalField>(),header);assert_eq!(std::mem::size_of::<Option<OriginalField>>(),header);assert_eq!(std::mem::size_of::<String>(),row["stringHeaderBytes"].as_u64().unwrap()as usize);
 for optional in [false,true]{
  let source=law["payload"].as_str().unwrap().to_owned();assert_eq!(serde_json::to_value(&source).unwrap(),law["payload"]);let source_capacity=source.capacity();let original=source.as_ptr();let mut original_source=Some(OriginalField{text:source,pointer:original as usize});let born=if optional{original_source.retirement_birth_bytes().unwrap()}else{semio_framework_value::retirement::deferred_birth_bytes_for(original_source.as_ref().unwrap())};let mut accept=|_|true;let mut native=NativeDecodeControl::new(law["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut accept);native.charge(born).unwrap();let(cursor,actual,released)=crate::test_allocation::observe_backing(||if optional{original_source.take().retirement()}else{semio_framework_value::retirement::deferred(original_source.take().unwrap())});assert_eq!((actual,released),(born,0));let mut cursor=cursor;assert_eq!(cursor.next_work_byte_demand().unwrap(),header);let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header-1,..caller};let(step,allocated,released)=crate::test_allocation::observe_backing(||cursor.close_step(denied));assert!(matches!(step,RetirementStep::BudgetExhausted));assert_eq!((allocated,released),(0,0));assert!(!cursor.terminal_is_empty());
  let child_birth=cursor.next_birth_bytes(header).unwrap();assert_eq!(child_birth,row["childBirthBytes"].as_u64().unwrap()as usize);native.charge(child_birth).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:header,..caller};let(step,allocated,released)=crate::test_allocation::observe_backing(||cursor.close_step(grant));let(mut child,progress)=match step{RetirementStep::ChildProgress(child,progress)=>(child,progress),_=>panic!("original field must return actual child and receipt in one admitted transfer")};assert!(cursor.terminal_is_empty());assert!(progress.fits(grant));assert_eq!((allocated,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!((progress.copied_items,progress.copied_bytes,progress.retained_capacity_bytes),(1,header,child_birth));let mut copied=progress.copied_bytes;let mut freed=0;let mut turns=0;
  while !child.terminal_is_empty(){turns+=1;assert!(turns<=law["maximumTurns"].as_u64().unwrap()as usize);let birth=child.next_birth_bytes(law["workBytes"].as_u64().unwrap()as usize).unwrap();native.charge(birth).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:law["workBytes"].as_u64().unwrap()as usize,..caller};let(step,allocated,released)=crate::test_allocation::observe_backing(||child.close_step(grant));assert_eq!(allocated,0);match step{RetirementStep::ProcessedBytes(bytes)=>{assert_eq!(released,0);copied+=bytes},RetirementStep::Bytes(bytes)=>{assert_eq!(released,bytes);freed+=bytes},RetirementStep::Complete=>assert_eq!(released,0),_=>panic!("original scalar child lost its exact payload")}}
  let(_,allocated,released)=crate::test_allocation::observe_backing(||drop(child));assert_eq!(allocated,0);freed+=released;let(_,allocated,released)=crate::test_allocation::observe_backing(||drop(cursor));assert_eq!(allocated,0);freed+=released;assert_eq!(copied,header+law["payloadBytes"].as_u64().unwrap()as usize);assert_eq!(freed,source_capacity+born+child_birth);assert_eq!(native.owned_bytes(),born+child_birth);assert!(native.owned_bytes()<law["nativeMaximumBytes"].as_u64().unwrap()as usize);assert!(!original.is_null());println!("[DEBUG] Original field child optional={} atomicHeader={} exactChildBirth={} originalNativeCeiling={} noNestedFrontier=true physicalTotalReleased={} independentSerde=true",optional,header,child_birth,law["nativeMaximumBytes"],freed);
 }
}

